'use strict';

// MODULES //

var hasOwnProp = require( '@stdlib/assert/has-own-property' );


// VARIABLES //

var SYMBOLS = {
	'arrow': 'arrow',
	'->': 'arrow',

	'asterisk': 'asterisk',
	'*': 'asterisk',

	'circle': 'circle',
	'o': 'circle',

	'cross': 'cross',
	'plus': 'cross',
	'+': 'cross',

	'diamond': 'diamond',
	'd': 'diamond',

	'dot': 'dot',
	'.': 'dot',

	'hexagram': 'hexagram',
	'h': 'hexagram',

	'line': 'line',
	'|': 'line',

	'square': 'square',
	's': 'square',

	'star': 'star',
	'pentagram': 'star',
	'p': 'star',

	'stroke': 'stroke',
	'_': 'stroke',

	'triangle': 'triangle',
	't': 'triangle',

	'triangle-down': 'triangle-down',
	'v': 'triangle-down',

	'triangle-left': 'triangle-left',
	'<': 'triangle-left',

	'triangle-right': 'triangle-right',
	'>': 'triangle-right',

	'triangle-up': 'triangle-up',
	'^': 'triangle-up',

	'wedge': 'wedge',
	'w': 'wedge',

	'x': 'x'
};


// MAIN //

/**
* Converts a symbol alias or shorthand to a canonical symbol alias.
*
* ## Notes
*
* -   For symbols having more than one accepted alias (e.g., `cross` and `plus`), the function returns the canonical alias.
* -   If unable to resolve an alias, the function returns `null`.
*
* @param {string} value - symbol alias or shorthand
* @returns {(string|null)} canonical symbol alias
*
* @example
* var v = symbol2alias( 'o' );
* // returns 'circle'
*
* v = symbol2alias( 'plus' );
* // returns 'cross'
*
* v = symbol2alias( 'beep' );
* // returns null
*/
function symbol2alias( value ) {
	if ( hasOwnProp( SYMBOLS, value ) ) {
		return SYMBOLS[ value ];
	}
	return null;
}


// EXPORTS //

module.exports = symbol2alias;
